#define SYS_getdents 217
#define BUF_SIZE 1024

struct linux_dirent {
    long d_ino;
    long d_off;
    unsigned short d_reclen;
    char d_name[]; 
};

char buffer[BUF_SIZE];
int dir_fd = 3; // File descriptor of open directory

// Invoke syscall directly
// Returns: total bytes read, 0 on EOF, -1 on error
int bytes_read = syscall(
    SYS_getdents, 
    dir_fd, 
    buffer, 
    BUF_SIZE
);

// Iteration starts: struct linux_dirent *d = (void*)buffer;
// Next entry: (void*)d + d->d_reclen;
// Stop when current pointer >= (void*)buffer + bytes_read
